"""No-model ASGI shutdown fixture; generated by the audit driver."""
import hashlib
import json
import os
from pathlib import Path
import socket
import sys
import uvicorn
import pllm._native

root = Path(sys.argv[1])
listener = socket.socket()
listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
listener.bind(("127.0.0.1", 0))
listener.listen(8)
identity = {"pid": os.getpid(), "port": listener.getsockname()[1],
            "native_path": pllm._native.__file__,
            "native_sha256": hashlib.sha256(Path(pllm._native.__file__).read_bytes()).hexdigest()}

async def app(scope, receive, send):
    if scope["type"] == "lifespan":
        while True:
            message = await receive()
            if message["type"] == "lifespan.startup":
                (root / "ready.json").write_text(json.dumps(identity))
                await send({"type": "lifespan.startup.complete"})
            elif message["type"] == "lifespan.shutdown":
                (root / "shutdown.json").write_text(json.dumps({"pid": os.getpid(), "lifespan_shutdown": True}))
                await send({"type": "lifespan.shutdown.complete"})
                return
    elif scope["type"] == "http":
        await send({"type": "http.response.start", "status": 200,
                    "headers": [(b"content-type", b"application/json")]})
        await send({"type": "http.response.body", "body": json.dumps(identity).encode()})

server = uvicorn.Server(uvicorn.Config(app, loop="asyncio", http="h11", lifespan="on",
                                      log_level="error", timeout_graceful_shutdown=1))
server.run(sockets=[listener])
